//! New exact quotient-ring/dense-work model, not native curve execution.
use num_bigint::BigInt;
use serde_json::{json,Value};
use std::{collections::BTreeMap,fs,path::Path};
use zopro_bn254::Fr;
#[path="split.rs"]mod split;
const ROOT:&str="/home/ubuntu/src/zopro-perf-work/tau9-ring-work176";
const WINDOWS:usize=18;const MODULUS:usize=19683;const RHO:[i128;2]=[81,162];
const LAMBDA:Fr=Fr::from_decimal("4407920970296243842393367215006156084916469457145843978461");
type Pair=[i128;2];
fn turn(v:Pair)->Pair{[-v[1],v[0]-v[1]]}fn norm(v:Pair)->i128{v[0]*v[0]-v[0]*v[1]+v[1]*v[1]}
fn mul(a:Pair,b:Pair)->Pair{[a[0]*b[0]-a[1]*b[1],a[0]*b[1]+a[1]*b[0]-a[1]*b[1]]}
fn unit(mut v:Pair,plane:usize,negative:bool)->Pair{for _ in 0..plane{v=turn(v);}if negative{[-v[0],-v[1]]}else{v}}
fn residue(v:Pair)->usize{let a=v[0].div_euclid(81);let b=v[1].div_euclid(81);(v[0].rem_euclid(81)+81*v[1].rem_euclid(81)+6561*(a+b).rem_euclid(3))as usize}
fn seed(r:usize)->Pair{[(r%81)as i128+81*(r/6561)as i128,((r/81)%81)as i128]}
fn nearest(v:Pair)->Pair{
    // Small table construction only. Input representatives/unit rotations
    // are small; full signed coordinates use divide-first recoding below.
    assert!(v.iter().all(|x|x.abs()<1000));
    let center=[(-v[0]+2*v[1]+121).div_euclid(243),(-2*v[0]+v[1]+121).div_euclid(243)];
    let mut best=None;for da in[-1,0,1]{for db in[-1,0,1]{let p=mul(RHO,[center[0]+da,center[1]+db]);let r=[v[0]-p[0],v[1]-p[1]];let score=(norm(r),r[0],r[1]);if best.is_none_or(|old|score<old){best=Some(score);}}}let(_,a,b)=best.unwrap();[a,b]
}
#[derive(Clone,Copy,Debug)]struct Digit{rep:usize,plane:usize,negative:bool,value:Pair}
struct Table{reps:Vec<Pair>,map:Vec<Option<Digit>>}
fn integer(v:Pair)->[BigInt;2]{v.map(BigInt::from)}
fn reconstruct(ds:&[Option<Digit>;WINDOWS])->[BigInt;2]{let mut z=[BigInt::from(0),BigInt::from(0)];for d in ds.iter().rev(){let[a,b]=z;z=[&a*81-&b*162,&a*162-&b*81];if let Some(d)=d{z[0]+=d.value[0];z[1]+=d.value[1];}}z}
fn field(x:i128)->Fr{let n=x.unsigned_abs();let f=Fr::from_canonical([n as u64,(n>>64)as u64,0,0]).unwrap();if x<0{-f}else{f}}
impl Table{
 fn new()->Self{let mut out=Self{reps:Vec::new(),map:vec![None;MODULUS]};for r in 1..MODULUS{if out.map[r].is_some(){continue;}let mut candidates=Vec::new();for plane in 0..3{for negative in[false,true]{candidates.push(nearest(unit(seed(r),plane,negative)));}}let rep=candidates.into_iter().min_by_key(|&x|(norm(x),x[0],x[1])).unwrap();assert!(norm(rep)<=6561);let index=out.reps.len();out.reps.push(rep);for plane in 0..3{for negative in[false,true]{let value=unit(rep,plane,negative);let class=residue(value);if let Some(old)=out.map[class]{assert_eq!(old.rep,index);}else{out.map[class]=Some(Digit{rep:index,plane,negative,value});}}}}assert!(out.map[0].is_none()&&out.map[1..].iter().all(Option::is_some));assert_eq!(out.reps.len(),3281);out}
 fn recode(&self,z:Pair)->[Option<Digit>;WINDOWS]{assert!(z.iter().all(|x|x.unsigned_abs()<(1u128<<126)));let mut q=z;let out=std::array::from_fn(|_|{let d=self.map[residue(q)];let digit=d.map(|d|d.value).unwrap_or([0,0]);let a=q[0].div_euclid(81)+(q[0].rem_euclid(81)-digit[0])/81;let b=q[1].div_euclid(81)+(q[1].rem_euclid(81)-digit[1])/81;assert_eq!((q[0].rem_euclid(81)-digit[0])%81,0);assert_eq!((q[1].rem_euclid(81)-digit[1])%81,0);assert_eq!((-a+2*b)%3,0);assert_eq!((-2*a+b)%3,0);q=[(-a+2*b)/3,(-2*a+b)/3];d});assert_eq!(q,[0,0]);assert_eq!(reconstruct(&out),integer(z));let rho=field(81)+LAMBDA*field(162);let got=out.iter().rev().fold(Fr::ZERO,|v,d|v*rho+d.map(|d|field(d.value[0])+LAMBDA*field(d.value[1])).unwrap_or(Fr::ZERO));assert_eq!(got,field(z[0])+LAMBDA*field(z[1]));out}
}
fn component(s:[u64;4],c:usize)->i128{let n=s[2*c]as u128|((s[2*c+1]&0x7fff_ffff_ffff_ffff)as u128)<<64;let x=i128::try_from(n).unwrap();if s[2*c+1]>>63!=0{-x}else{x}}
fn add(a:Pair,b:Pair,p:i128)->Pair{std::array::from_fn(|j|(a[j]+b[j]).rem_euclid(p))}fn scale(a:Pair,k:i128,p:i128)->Pair{std::array::from_fn(|j|(a[j]*k).rem_euclid(p))}fn apply(a:Pair,v:Pair,p:i128)->Pair{add(scale(a,v[0],p),scale(turn(a),v[1],p),p)}
fn token(i:usize,p:i128)->Pair{[((i as i128+1)*7919+37)%p,((i as i128+1)*104729+101)%p]}
#[derive(Clone,Default)]struct Bucket{n:u64,token:[Pair;2]}
fn model(table:&Table,rows:&[(usize,Pair)],n:usize)->Value{let size=table.reps.len();let mut ring=vec![vec![vec![Bucket::default();size];6];WINDOWS];let primes=[65537i128,1000000007];let mut expected=vec![[[0i128;2];2];WINDOWS];for &(index,z)in rows{let part=usize::from(index>=n.div_ceil(2));for(w,d)in table.recode(z).into_iter().enumerate(){if let Some(d)=d{let b=&mut ring[w][3*part+d.plane][d.rep];b.n+=1;for(j,&p)in primes.iter().enumerate(){let t=token(index,p);b.token[j]=add(b.token[j],scale(t,if d.negative{-1}else{1},p),p);expected[w][j]=add(expected[w][j],apply(t,d.value,p),p);}}}}
let mut result=Vec::new();let mut total=0u64;let mut phi=0u64;for w in 0..WINDOWS{let arrivals=ring[w].iter().flatten().map(|b|b.n).sum::<u64>();let first=ring[w].iter().flatten().filter(|b|b.n>0).count()as u64;let mut occupied=0u64;let mut refs=[0u64;2];let mut axes:[BTreeMap<usize,([Pair;2],u64)>;2]=std::array::from_fn(|_|BTreeMap::new());let mut maps=0u64;for(i,&rep)in table.reps.iter().enumerate(){let live=(0..6).filter(|&p|ring[w][p][i].n>0).collect::<Vec<_>>();if live.is_empty(){continue;}occupied+=1;let mut point=[[0;2];2];for &plane in &live{if plane%3!=0&&(plane<3||ring[w][plane-3][i].n==0){maps+=1;}for(j,&p)in primes.iter().enumerate(){let t=(0..plane%3).fold(ring[w][plane][i].token[j],|t,_|turn(t));point[j]=add(point[j],t,p);}}for axis in 0..2{let k=rep[axis];if k==0{continue;}refs[axis]+=1;let e=axes[axis].entry(k.unsigned_abs()as usize).or_insert(([[0;2];2],0));e.1+=1;for(j,&p)in primes.iter().enumerate(){e.0[j]=add(e.0[j],scale(point[j],k.signum(),p),p);}}}
let count=axes.each_ref().map(|a|a.len()as u64);let max=axes.each_ref().map(|a|a.keys().next_back().copied().unwrap_or(0));let grouping=refs.iter().sum::<u64>()-count.iter().sum::<u64>();let weighted=max.map(|m|2*(m as u64).saturating_sub(1)).iter().sum::<u64>();let combine=u64::from(!axes[0].is_empty()&&!axes[1].is_empty());let merging=first-occupied;let adds=arrivals-first+merging+grouping+weighted+combine;let mut totals=[[[0;2];2];2];for axis in 0..2{for(&k,(v,_))in &axes[axis]{for(j,&p)in primes.iter().enumerate(){totals[axis][j]=add(totals[axis][j],scale(v[j],k as i128,p),p);}}}for(j,&p)in primes.iter().enumerate(){assert_eq!(add(totals[0][j],turn(totals[1][j]),p),expected[w][j]);}total+=adds;phi+=maps;result.push(json!({"position":w,"arrivals":arrivals,"first_assignments":first,"occupied_representatives":occupied,"stream_pairs":arrivals-first,"part_unit_merges":merging,"axis_references":refs,"occupied_axes":count,"maximum_axis_weights":max,"axis_grouping":grouping,"dense_weighted_pairs":weighted,"axis_combinations":combine,"generic_adds":adds,"unit_phi_maps":maps,"formal_token_checks":2}));}
json!({"rows_checked":rows.len(),"generic_addition_model_total":total,"unit_phi_maps":phi,"unit_phi_Fq_multiplications":2*phi,"axis_result_phi_maps_separate":WINDOWS,"rho_Horner_calls_separate":WINDOWS-1,"Horner_identity":"rho=tau^9=81phi*tau, four triplings plus one tau and one unit map per call; all costs unpriced","rows":result})}
fn main(){assert!(!Path::new(&format!("{ROOT}/analysis.json")).exists());let table=Table::new();let mut orbit_counts=vec![0usize;table.reps.len()];for(class,d)in table.map.iter().enumerate().skip(1){let d=d.unwrap();assert_eq!(residue(d.value),class);assert_eq!(unit(table.reps[d.rep],d.plane,d.negative),d.value);assert_eq!(residue(seed(class)),class);orbit_counts[d.rep]+=1;table.recode(seed(class));}assert_eq!(orbit_counts.iter().filter(|&&n|n==2).count(),1);assert!(orbit_counts.iter().all(|&n|n==2||n==6));let mut tau=[1,0];for _ in 0..9{tau=mul(tau,[1,-1]);}assert_eq!(tau,RHO);assert_eq!(norm(RHO),MODULUS as i128);assert!((BigInt::from(140).pow(18)*58)>((BigInt::from(1)<<127usize)*139));
let edge=[-((1i128<<126)-1),-244,-243,-162,-81,-1,0,1,81,162,243,244,(1i128<<126)-1];let mut edge_cases=0;for a in edge{for b in edge{table.recode([a,b]);edge_cases+=1;}}let mut s=0x746175392d72696e672d6d6f64656c01u128;for _ in 0..10000{s^=s<<23;s^=s>>17;s^=s<<26;let a=(s&((1<<126)-1))as i128;s=s.rotate_left(53);let b=(s&((1<<126)-1))as i128;table.recode([if s&1==0{a}else{-a},if s&2==0{b}else{-b}]);}
let inputs:Value=serde_json::from_slice(&fs::read(format!("{ROOT}/inputs.json")).unwrap()).unwrap();let prior:Value=serde_json::from_slice(&fs::read("/home/ubuntu/src/zopro-perf-work/g2-joint-ring-screen176/analysis.json").unwrap()).unwrap();let mut cases=Vec::new();for(name,input)in inputs.as_object().unwrap(){let bytes=fs::read(input["file"].as_str().unwrap()).unwrap();assert_eq!(&bytes[..8],b"B2SCAN01");let n=u64::from_le_bytes(bytes[8..16].try_into().unwrap())as usize;assert_eq!(bytes.len(),16+160*n);let mut rows=Vec::new();for i in 0..n{let words=std::array::from_fn(|j|u64::from_le_bytes(bytes[16+128*n+32*i+8*j..16+128*n+32*i+8*j+8].try_into().unwrap()));let raw=Fr::from_canonical(words).unwrap();if bytes[16+128*i..16+128*(i+1)].iter().all(|&b|b==0){continue;}let split=split::phi_split(words);let z=[component(split,0),component(split,1)];assert_eq!(field(z[0])+LAMBDA*field(z[1]),raw);rows.push((i,z));}let candidate=model(&table,&rows,n);let old=prior["cases"].as_array().unwrap().iter().find(|c|c["case"]==*name).unwrap();let accepted=old["model"]["baseline_full_dense"]["generic_addition_model_total"].as_u64().unwrap();let binary=old["model"]["ring"]["generic_addition_model_total"].as_u64().unwrap();let total=candidate["generic_addition_model_total"].as_u64().unwrap();cases.push(json!({"case":name,"raw_rows":n,"tau9":candidate,"inherited_accepted_dense_adds":accepted,"inherited_binary128_dense_adds":binary,"less_than_accepted":total<accepted,"less_than_prior_binary":total<binary,"necessary_work_gate":total<accepted&&total<binary}));}
let gate=cases.iter().find(|c|c["case"]=="1x2-B").unwrap()["necessary_work_gate"].as_bool().unwrap();let result=json!({"complete":true,"rho":RHO,"rho_norm":MODULUS,"windows":WINDOWS,"representatives":table.reps.len(),"residue_classes":MODULUS,"two_class_nonzero_orbits":1,"six_class_nonzero_orbits":3280,"max_representative_norm":table.reps.iter().map(|&x|norm(x)).max().unwrap(),"all_nonzero_classes_checked":MODULUS-1,"signed_edge_pairs":edge_cases,"random_signed_pairs":10000,"integer_and_Fr_reconstruction":true,"termination_integer_inequality_passed":true,"theoretical_packed_metadata_bytes":MODULUS*2+table.reps.len()*4,"metadata_not_a_native_allocation_or_key_table":true,"cases":cases,"necessary_primary_work_gate":gate,"native_selected":false,"further_exact_census_permitted":gate,"new_timings":0,"new_proofs":0,"canonical_proofs_unchanged":35171,"production_changed":false,"goal_complete":false});fs::write(format!("{ROOT}/analysis.json"),serde_json::to_vec_pretty(&result).unwrap()).unwrap();println!("Newtau9exactrecoder/workmodelPASS; 19683classes/3281representatives/18positions; necessaryprimarygate={gate}; no native clocks or proofs");}
